        left, right = 0, len(arr) - 1
        first = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                first = mid
                right = mid - 1
            elif arr[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        return first

    # Function to find the last occurrence of x in the sorted array
    def find_last(arr, x):
        left, right = 0, len(arr) - 1
        last = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                last = mid
                left = mid + 1
            elif arr[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        return last

    first_index = find_first(arr, x)
    last_index = find_last(arr, x)

    if first_index != -1 and last_index != -1:
        count = last_index - first_index + 1
        return count > n // 2
    else:
        return False
